 dd 4

DaysOfYearByMonth_A:
 dw #1 #32 #60 #91 #121 #152 #182 #213 #244 #274 #305 #335 #366
DaysOfYearByMonth_B:
 dw #1 #32 #61 #92 #122 #153 #183 #214 #245 #275 #306 #336 #367

ConvertRoutine:
 push rcx
 push rdx
 push r8
 push r9
 push r10
 push r11
 push r12

   { 1900-01-01  => 076C0001 }
   { 15-Sep-2020 => 07E40103 }
   { 20-Jun-2021 => 07E500AB }

 xor rax, rax
 mov eax, dword ptr [rcx] { grab memory address }

 xor r9, r9
 mov r9d, eax  {store original value in r9}

 cmp eax, 073A0000 { year 1850 }
 jle convert_exit
 cmp eax, 08020000 { year 2050 }
 jge convert_exit

 and eax, 1FF
 cmp eax, 0         { check day of year invalid }
 jle convert_exit
 cmp eax, 368       { check day of year invalid }
 jge convert_exit

 mov rax, r9  {restore original value to rax}
 mov r12, rax {store original value in r12}

 { store day of year }
 mov r10, r12
 shr r10, #16

 xor r11, r11 { leap year flag }
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #4
 idiv r8d
 cmp rdx, 0
 jne @f
 mov r11, 1 {probably leap}
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #100
 idiv r8d
 cmp rdx, 0
 jne @f
 xor r11, r11 {possibly not leap}
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #400
 idiv r8d
 cmp rdx, 0
 jne @f
 mov r11, 1 { is special case leap}
@@:

 { store 15 minute intervals since 6 AM }
 //xor r8, r8
 //mov r8w, r12w
 //shr r8, #17

 { store days in year }
 mov rax, r12
 and rax, 1FF

 imul r9, r10, #10000 { r9 = year * 10000 }
 { load day start, check leap year }
 cmp r11, 1
 lea r11, [DaysOfYearByMonth_A]
 jne @f
 lea r11, [DaysOfYearByMonth_B]
@@:
 mov r10, rax
 {search days array}
 xor rax, rax
 xor rcx, rcx
 mov rcx, #12
 add r11, #24    { start at back and advance forward }
do_days:
 sub r11, #2     { offsets are word based }
 mov eax, [r11]
 cmp r10w, ax    { compare the word if greater then }
 jge end_days
 loop do_days
end_days:
 imul rax, rcx, #100   { ecx - month, eax - day }
 add r9d, eax { r9 += month * 100 }
 xor rax, rax
 mov ax, [r11]
 sub r10d, eax  { remove the offset of day of year by month }
 inc r10d { 1-based offset }
 add r9d, r10d { r9 += day * 1 }

convert_exit:
 mov rax, r9 { final result }

 pop r12
 pop r11
 pop r10
 pop r9
 pop r8
 pop rdx
 pop rcx
 ret

ConvertBackRoutine:
push rax
push rcx
push rdx
push r8
push r9
push r10
push r11
push r12
push r13
push r14

 xor r13, r13
 mov r13d, ecx { r13 - starting value }
 xor r14, r14
 mov r14d, dword ptr [rdx] { original value at final location }

 { begin compile }
 mov rax, r13
 cdq
 xor rdx, rdx
 mov r8, #10000
 idiv r8
 mov r10, rax { store year to r10 }
 mov r9, rdx {store monthday remainder }

 shl rax, #16
 mov r12, rax { add year to result }

 // get leap year
 xor r11, r11 { leap year flag }
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #4
 idiv r8d
 cmp rdx, 0
 jne @f
 mov r11, 1 {probably leap}
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #100
 idiv r8d
 cmp rdx, 0
 jne @f
 mov r11, 0 {possibly not leap}
 cdq
 xor rdx, rdx
 mov rax, r10
 mov r8d, #400
 idiv r8d
 cmp rdx, 0
 jne @f
 mov r11, 1 {leap}
@@:

 { load day start, check leap year }
 cmp r11, 1
 lea r11, [DaysOfYearByMonth_A]
 jne @f
 lea r11, [DaysOfYearByMonth_B]
@@:
 mov rax, r9 { copy monthday remainder to rax }
 cdq
 xor rdx, rdx
 mov r8, #100 { get month }
 idiv r8
 dec rax { from from 1-based to 0-based }
 add rax, rax {double}
 add r11, rax
 mov ax, word ptr [r11] { lookup days from month }
 and rax, FF
 dec rax { from from 1-based to 0-based }
 add ax, dx { add day offset to start of month }
 add r12, rax { add day of year to result }

 mov eax, r14d // grab time from current value
 and rax, 0000FE00 {mask time out }
 or r12, rax { store time in result }

 mov rax, r12  {end value in r12, return via rax }

convert_back_exit:
pop r14
pop r13
pop r12
pop r11
pop r10
pop r9
pop r8
pop rdx
pop rcx
mov dword ptr [rdx],eax
pop rax

ret
]]
  L8_1(L9_1)
  L8_1 = "_globalsRegistered"
  L9_1 = true
  _ENV[L8_1] = L9_1
end
L8_1 = FMCETableHelpers
return L8_1
